#!/usr/bin/env python3
"""PreToolUse guard: keeps Claude out of generated files and away from irreversible commands."""

from __future__ import annotations

import re
from fnmatch import fnmatch

from _common import ask, committed, deny, project_path, read_event, tool_input

# (path or directory prefix, why it must not be edited by hand)
GENERATED = [
    ("backend/vendor/", "Composer-managed. Change backend/composer.json and run Composer in the backend container."),
    ("backend/var/", "Symfony cache and logs; rebuilt on demand."),
    ("backend/config/reference.php", "Regenerated by Symfony on every cache:clear (Rector skips it for the same reason)."),
    ("backend/composer.lock", "Update it with `docker compose exec backend composer require|update <package>`."),
    ("backend/symfony.lock", "Maintained by Symfony Flex when recipes run."),
    ("frontend/node_modules/", "npm-managed. Change frontend/package.json and run npm."),
    ("frontend/dist/", "Output of `npm run build`."),
    ("frontend/.wrangler/", "Wrangler's local state."),
    ("frontend/package-lock.json", "Update it with `npm install <package>` / `npm update` in frontend/."),
]

# A compose project named "<repo>-dep-check" is the dependency-upgrader agent's disposable
# copy of the stack, so deleting its volumes destroys nothing of the user's.
DEP_CHECK = re.compile(r"(-p|--project-name)[ =]\S*dep-check\b")
DELETES_VOLUMES = re.compile(r"\bdocker[- ]compose\b[^;&|]*\bdown\b[^;&|]*(\s-v\b|--volumes)|\bdocker\s+volume\s+(rm|prune)\b")
SCHEMA_UPDATE = re.compile(r"doctrine:schema:(update|drop)\b")
DEPLOY = re.compile(r"\bwrangler\s+deploy\b|\bnpm\s+(--prefix\s+\S+\s+)?run\s+deploy\b")


def check_bash(command: str) -> None:
    if command.lstrip().startswith("git "):
        return  # commit messages and the like only mention these commands
    if SCHEMA_UPDATE.search(command):
        deny(
            "Schema changes go through Doctrine migrations: `docker compose exec backend php bin/console make:migration`, "
            "review the SQL, then `doctrine:migrations:migrate`. schema:update would leave production, which only runs migrations, behind."
        )
    if DELETES_VOLUMES.search(command) and not DEP_CHECK.search(command):
        ask("Deletes the db_data volume: every account and score in the local database.")
    if DEPLOY.search(command):
        ask("Publishes the SPA and its proxy Worker to Cloudflare production.")


def check_edit(rel: str) -> None:
    for prefix, reason in GENERATED:
        if rel == prefix or (prefix.endswith("/") and rel.startswith(prefix)):
            deny(f"{rel} is not hand-edited: {reason}")
    if fnmatch(rel, "backend/migrations/Version*.php") and committed(rel):
        deny(
            f"{rel} is a committed migration. It has already run on other databases (Render runs pending "
            "migrations at boot), so editing it changes nothing there. Generate a new one with "
            "`docker compose exec backend php bin/console make:migration`."
        )


def main() -> None:
    event = read_event()
    if event.get("tool_name") == "Bash":
        check_bash(tool_input(event).get("command", ""))
        return
    rel = project_path(event)
    if rel is not None:
        check_edit(rel)


if __name__ == "__main__":
    main()
